export type ModelInfo = { provider: string; modelId: string };
type TelemetryOptions = { functionId?: string; isEnabled?: boolean };
type InferEvent<EVENT> = EVENT & Omit<TelemetryOptions, "isEnabled">;
/** Reached by a consumer only through the alias application's flattened arms. */
export type CallStartEvent = ModelInfo & { messages: string[] };
type Callback<EVENT> = (event: EVENT) => void;
export interface Telemetry {
    onCallStart?: Callback<InferEvent<CallStartEvent>>;
}
